mapper.select:
/*selectMasterMpVoVocProgressStateList*/ SELECT ROWNUM NUM, X.CLAIM_TEXT, X.VC_NO, X.CD_DATE, X.PO_NO, X.BUYER_ITEM_NO, X.CD_USER_NAME, X.DS_USER_NAME, X.BUYER_NAME, X.REQ_USER_NAME, X.REQ_DATE, X.DF_DATE, X.RECV_FLAG_TEXT, X.RUB_TYPE, X.CLAIM_GRADE, X.CD_DEPT_NAME, X.CLAIM_TYPE, X.RECV_FLAG, X.CD_USER_ID, X.DS_USER_ID, X.BUYER, X.LEAD_TIME, X.DS_DEPT, X.DS_DEPT_NAME, X.DS_CHANGE_FLAG, X.DS_CHANGE_DATE, X.CLAIM_MASTER_TEXT, X.MRO_AREA_TEXT, X.REQ_USER_TEL, X.CLAIM_MASTER, X.SYS_TYPE, X.SYS_FLAG, X.REVISION, X.RE_REQ_USER_NAME, X.RE_REQ_DATE, X.DS_DATE, X.CANCEL_USER_NAME, X.CANCEL_NOTE, X.CANCEL_DATE, X.PH_DATE FROM ( SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = A.CLAIM_TYPE) AS CLAIM_TEXT, A.VC_NO, TO_CHAR(A.CD_DATE,'YYYYMMDD') AS CD_DATE, A.PO_NO, A.BUYER_ITEM_NO, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.CD_USER_ID AND SYS_TYPE='KA') AS CD_USER_NAME, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.DS_USER_ID AND SYS_TYPE='KA') AS DS_USER_NAME, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE = A.BUYER AND SYS_TYPE=A.SYS_TYPE AND BUSINESS_COND LIKE '%B%') AS BUYER_NAME, A.REQ_USER_NAME AS REQ_USER_NAME, TO_CHAR(A.REQ_DATE,'YYYY/MM/DD HH24:MI') AS REQ_DATE, TO_CHAR(A.DF_DATE,'YYYYMMDD') AS DF_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC02' AND CODE = A.RECV_FLAG) AS RECV_FLAG_TEXT, DECODE(A.RUB_TYPE,'A','매우만족','B','만족','C','보통','D','불만','F','매우불만','미평가') AS RUB_TYPE, A.CLAIM_GRADE, (SELECT TEXT1 FROM V_VOC_ICOMCOD2 WHERE COMPANY_CODE='KRKORE0001' AND TYPE='C001' AND CODE=A.CD_DEPT AND SYS_TYPE='KA') AS CD_DEPT_NAME, A.CLAIM_TYPE, A.RECV_FLAG, A.CD_USER_ID, A.DS_USER_ID, A.BUYER, ROUND(A.DF_DATE-A.CD_DATE,1) AS LEAD_TIME, A.DS_DEPT, (SELECT TEXT1 FROM V_VOC_ICOMCOD2 WHERE COMPANY_CODE='KRKORE0001' AND TYPE='C001' AND CODE=A.DS_DEPT AND SYS_TYPE='KA') AS DS_DEPT_NAME, A.DS_CHANGE_FLAG AS DS_CHANGE_FLAG, TO_CHAR(A.DS_CHANGE_DATE, 'YYYYMMDD') AS DS_CHANGE_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC03' AND CODE = A.CLAIM_MASTER) AS CLAIM_MASTER_TEXT, A.MRO_AREA_TEXT AS MRO_AREA_TEXT, A.REQ_USER_TEL AS REQ_USER_TEL, A.CLAIM_MASTER AS CLAIM_MASTER, A.SYS_TYPE, A.SYS_FLAG, (SELECT COUNT(REVISION) FROM KEP_VOC_REVISION WHERE VC_NO = A.VC_NO) AS REVISION, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.RE_REQ_USER_ID AND SYS_TYPE='KA') AS RE_REQ_USER_NAME, TO_CHAR(A.RE_REQ_DATE,'YYYY/MM/DD HH24:MI') AS RE_REQ_DATE, TO_CHAR(A.DS_DATE,'YYYY/MM/DD HH24:MI') AS DS_DATE, (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.CANCEL_USER_ID) AS CANCEL_USER_NAME, A.CANCEL_NOTE, TO_CHAR(A.CANCEL_DATE,'YYYY/MM/DD HH24:MI') AS CANCEL_DATE, TO_CHAR(A.PH_DATE,'YYYY/MM/DD HH24:MI') AS PH_DATE FROM KEPAVCDT A WHERE TO_CHAR(A.REQ_DATE,'YYYYMMDD') BETWEEN REPLACE(#{st_from_date}, '/', '') AND REPLACE(#{st_to_date}, '/', '')
AND A.BUYER IN ( SELECT a.buyer FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} /**P*/ AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT BUYER FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} /**P*/ UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} /**P*/ AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND A.PO_NO LIKE UPPER('%' || #{st_po_item_no} || '%')
AND A.BUYER_ITEM_NO LIKE UPPER('%' || #{st_po_item_no} || '%')
AND A.VC_NO LIKE UPPER('%' || #{st_po_item_no} || '%')
AND ((TO_CHAR(A.DF_DATE,'YYYYMMDD') - TO_CHAR(A.REQ_DATE,'YYYYMMDD')) >= #{st_lead_time} AND A.RECV_FLAG = 'FB')
AND ((TO_CHAR(A.DF_DATE,'YYYYMMDD') - TO_CHAR(A.REQ_DATE,'YYYYMMDD')) = #{st_lead_time} AND A.RECV_FLAG = 'FB')
AND A.SYS_TYPE = #{st_sys_type}
AND A.BUYER = #{st_buyer_code}
AND A.CD_USER_ID = #{st_cd_user_id}
AND A.DS_USER_ID = #{st_ds_user_id}
AND A.RECV_FLAG = #{st_recv_flag}
AND A.DS_DEPT = #{st_ds_dept}
ORDER BY A.REQ_DATE DESC ) X

mapper.update:

/*deleteMasterMpVoVocProgressState*/
		UPDATE KEPAVCDT					
		   SET RECV_FLAG      = 'GD' 	
		     , CANCEL_USER_ID = #{st_user_id} 
		     , CANCEL_DATE    = SYSDATE	
		     , CANCEL_NOTE  = #{CANCEL_NOTE}
		 WHERE VC_NO          = #{VC_NO}
